CREATE TABLE IF NOT EXISTS students (student_id text PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS events (event_id text PRIMARY KEY,title text NOT NULL,description text NOT NULL DEFAULT '',capacity integer NOT NULL CHECK(capacity>0),registration_open_at timestamptz NOT NULL,registration_close_at timestamptz NOT NULL,start_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('DRAFT','PUBLISHED','REGISTRATION_OPEN','REGISTRATION_CLOSED','COMPLETED','CANCELLED')),CHECK(registration_open_at<registration_close_at));
CREATE TABLE IF NOT EXISTS registrations (registration_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,student_id text NOT NULL REFERENCES students(student_id),event_id text NOT NULL REFERENCES events(event_id),registered_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','CANCELLED','ATTENDED','NO_SHOW')),UNIQUE(student_id,event_id));
